function useBackOverlay(close, isOpen = true) {
  const closeRef = g.useRef(close);
  g.useLayoutEffect(() => { closeRef.current = close; }, [close]);
  g.useEffect(() => {
    if (isOpen) return registerBackOverlay(() => closeRef.current());
  }, [isOpen]);
}

async function exportAndNotify(filename, contents, type, notify, successMessage) {
  try {
    const platform = await exportFile(filename, contents, type);
    if (platform === 'web') notify(successMessage);
  } catch {
    notify('无法导出文件，请重试。', true);
  }
}

